import React, { useState } from 'react';
import { OrbMain } from '../components/Orb';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

const G = {
  page: { position: 'relative', minHeight: '100vh', background: '#EEEAE3', overflow: 'hidden' },
  inner: { display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: '100vh', padding: '56px 28px 110px', position: 'relative', zIndex: 10 },
};

export default function Home({ setPage, streak }) {
  const [inputOpen, setInputOpen] = useState(false);
  const [text,      setText]      = useState('');
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');
  const [result,    setResult]    = useState(null);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id: Date.now(), user_text: text, ...ai, date: new Date().toISOString() };
      addThought(entry);
      setResult(entry);
      setInputOpen(false);
    } catch { setError('Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={G.page}>
      <OrbMain />

      {/* Loading overlay */}
      {loading && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 250, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 20, background: 'rgba(238,234,227,0.7)', backdropFilter: 'blur(12px)' }}>
          <div style={{ width: 72, height: 72, borderRadius: '50%', background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)', animation: 'loadPulse 1.2s ease-in-out infinite' }} />
          <p style={{ fontSize: 13, fontWeight: 500, color: 'rgba(26,42,42,0.4)' }}>Analyserar…</p>
        </div>
      )}

      <div style={G.inner}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 13, fontWeight: 600, letterSpacing: '-0.03em', color: 'rgba(26,42,42,0.4)' }}>spiral</span>
          {streak > 0 && (
            <div style={{ padding: '7px 14px', borderRadius: 999, background: 'rgba(26,42,42,0.07)', fontSize: 12, fontWeight: 500, color: '#2D6B6B' }}>
              🔥 {streak} dagar
            </div>
          )}
        </div>

        <div>
          <h1 style={{ fontSize: 42, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 32 }}>
            Vad snurrar<br />i ditt <span style={{ color: '#2D6B6B' }}>huvud?</span>
          </h1>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <button onClick={() => setInputOpen(true)} style={{ width: '100%', padding: 18, borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600, letterSpacing: '-0.02em', transition: 'all 0.2s' }}>
              Analysera en tanke
            </button>
            <button onClick={() => setPage('checkin')} style={{ width: '100%', padding: 16, borderRadius: 20, background: 'rgba(26,42,42,0.07)', color: '#2D6B6B', fontSize: 15, fontWeight: 500, letterSpacing: '-0.01em' }}>
              Daglig check-in
            </button>
          </div>
        </div>
      </div>

      {/* Input sheet */}
      {inputOpen && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 200, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', background: 'rgba(20,32,32,0.25)', backdropFilter: 'blur(4px)', animation: 'fadeIn 0.3s ease' }}>
          <div onClick={() => setInputOpen(false)} style={{ flex: 1 }} />
          <div style={{ margin: '0 10px 12px', borderRadius: 32, padding: '28px 24px 24px', background: 'rgba(238,234,227,0.97)', backdropFilter: 'blur(40px)', border: '1px solid rgba(255,255,255,0.8)', boxShadow: '0 -8px 60px rgba(26,42,42,0.12)', animation: 'slideUp 0.4s cubic-bezier(0.16,1,0.3,1)', position: 'relative' }}>
            <button onClick={() => setInputOpen(false)} style={{ position: 'absolute', top: 24, right: 24, width: 30, height: 30, borderRadius: '50%', background: 'rgba(26,42,42,0.07)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, color: 'rgba(26,42,42,0.4)' }}>✕</button>
            <div style={{ fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 14 }}>Din tanke</div>
            <textarea
              autoFocus
              value={text}
              onChange={e => setText(e.target.value)}
              maxLength={1000}
              placeholder="Skriv fritt…"
              style={{ width: '100%', minHeight: 130, background: 'transparent', border: 'none', outline: 'none', fontSize: 18, lineHeight: 1.65, color: '#1A2A2A', fontWeight: 400, resize: 'none' }}
            />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: 16, borderTop: '1px solid rgba(26,42,42,0.08)', marginTop: 6 }}>
              <span style={{ fontSize: 12, color: 'rgba(26,42,42,0.25)' }}>{text.length} / 1000</span>
              <button
                onClick={submit}
                disabled={!text.trim() || loading}
                style={{ padding: '12px 24px', borderRadius: 999, background: text.trim() && !loading ? '#1A2A2A' : 'rgba(26,42,42,0.1)', color: text.trim() && !loading ? '#EEEAE3' : 'rgba(26,42,42,0.25)', fontSize: 13, fontWeight: 600, transition: 'all 0.2s' }}
              >
                Analysera →
              </button>
            </div>
            {error && <p style={{ fontSize: 12, color: 'rgba(200,80,80,0.8)', marginTop: 10 }}>{error}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

